WITH cleaned AS (SELECT id, full_name, email, dept_id, job_title, hire_date, is_remote, level, CAST(is_remote AS INT) AS is_remote_flag, DATEDIFF(CURRENT_DATE(), hire_date) AS days_since_hire_date FROM employees WHERE hire_date >= DATE '2023-04-26' AND job_title IS NOT NULL), enriched AS (SELECT e.*, d.dept_name FROM cleaned e INNER JOIN departments d ON e.dept_id = d.id), deduped AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY level ORDER BY hire_date DESC NULLS FIRST, id) AS rn FROM enriched QUALIFY rn = 1), metrics AS (SELECT id, full_name, email, dept_id, job_title, hire_date, is_remote, is_remote_flag, days_since_hire_date, dept_name, rn, SUM(is_remote_flag) OVER (PARTITION BY dept_name ORDER BY hire_date, id ROWS BETWEEN 3 PRECEDING AND CURRENT ROW) AS last4_sum_is_remote_flag, MAX(is_remote_flag) OVER (PARTITION BY dept_name ORDER BY hire_date, id ROWS BETWEEN 3 PRECEDING AND CURRENT ROW) AS last4_max_is_remote_flag, MIN(is_remote_flag) OVER (PARTITION BY dept_name ORDER BY hire_date, id ROWS BETWEEN 3 PRECEDING AND CURRENT ROW) AS last4_min_is_remote_flag, COUNT(is_remote_flag) OVER (PARTITION BY dept_name ORDER BY hire_date, id ROWS BETWEEN 3 PRECEDING AND CURRENT ROW) AS last4_count_is_remote_flag FROM deduped WHERE hire_date <= '2024-07-16') SELECT d.dept_name AS department_dept_name, e.job_title, COUNT(*) AS rows_total, MAX(e.last4_sum_is_remote_flag) AS max_last4_sum_is_remote_flag, MAX(e.last4_max_is_remote_flag) AS max_last4_max_is_remote_flag, GROUPING_ID() AS level_id FROM metrics e LEFT JOIN departments d ON e.dept_id = d.id GROUP BY CUBE (d.dept_name, e.job_title) ORDER BY job_title DESC NULLS LAST;
